head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL16604";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16604.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fnSearch, tx_fnView) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.fnSearch();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16604.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_appDtllList_oncellclick
 * @description grd_appDtllList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_appDtllList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_appDtllList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_appDtllList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.fnView(r["comSchdlId"], r["comSchdlTpCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_appDtllList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_50_onclick
 * @description krxpage_pagenavigator_50 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_50_onclick = async function (index) {
    try {
    const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; await scwin.fnSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil16604.krxpage_pagenavigator_50_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch
 * @description fn Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnSearchReq",
        target: "dlt_appDtllList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnView
 * @description fn View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnView = async function () {
    const sbmOptions = {
        id: "tx_fnView",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnViewReq",
        target: "dlt_appDtllList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_appDtllList_fmt_schdlAcptStrtDd
 * @description grd app Dtll List fmt schdl Acpt Strt Dd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_appDtllList_fmt_schdlAcptStrtDd = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_appDtllList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "schdlStatTpCd") ?? '') : '');
        if (v === '0') { return (console.error('[sdd] 미실현 라벨 갈래: schdlAcptStrtDd (expression)'), String(data ?? '')); }
        if (v === '1') { return "확정[수정불가]"; }
        if (v === '2') { return "접수마감"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_appDtllList.schdlAcptStrtDd" }); return String(data ?? ''); }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent('ipt_method').setValue("comSprtSvcApplDtlList");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnSearch();
};

/**
 * @method
 * @name fnView
 * @description fn View 처리
 * @param {String} ipt_comSchdlId ipt_comSchdlId
 * @param {String} ipt_comSchdlTpCd ipt_comSchdlTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnView = async function (ipt_comSchdlId, ipt_comSchdlTpCd) {
    $c.util.getComponent('ipt_comSchdlId').setValue(ipt_comSchdlId);
    $c.util.getComponent('ipt_comSchdlTpCd').setValue(ipt_comSchdlTpCd);
    $c.util.getComponent('ipt_method').setValue("comSprtSvcApplView");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    await scwin.tx_fnView();
};
